import { PartialType } from '@nestjs/mapped-types';

export class CreateUserDto {
  @IsEmail() email: string;
  @MinLength(8) password: string;
}

// every field optional, original decorators preserved for fields that ARE sent
export class UpdateUserDto extends PartialType(CreateUserDto) {}

@Patch(':id')
update(@Param('id') id: string, @Body() dto: UpdateUserDto) {
  return this.users.update(id, dto);
}

Why: PartialType(CreateUserDto) builds a DTO where every inherited field is optional (applies @IsOptional() field-by-field) while keeping each field's original rule for when it IS present — so { email } alone validates AND a sent password is still length-checked. Do NOT use skipMissingProperties: true: it relaxes validation for ANY missing property across EVERY DTO in the app, including genuinely-required fields elsewhere, so a forgotten required field passes silently. PartialType scopes the optionality to exactly this one update DTO. (If you need to distinguish 'field absent' from 'field sent as null', add @IsDefined()/@ValidateIf on top — @IsOptional() alone treats both as fine.)

